cedar.statement:
forbid(
  principal is AgentCore::OAuthUser,
  action == AgentCore::Action::"ReviewerTools___record_adverse_determination",
  resource == AgentCore::Gateway::"<reviewer-gateway-arn>"
) when { principal == AgentCore::OAuthUser::"<agent-client-id>" || !(principal.hasTag("pa_role") && principal.getTag("pa_role") == "clinician") };

permit(
  principal == AgentCore::OAuthUser::"<agent-client-id>",
  action in [AgentCore::Action::"AgentTools___check_eligibility", AgentCore::Action::"AgentTools___fetch_policy_criteria", AgentCore::Action::"AgentTools___extract_clinical_evidence", AgentCore::Action::"AgentTools___route_to_reviewer"],
  resource == AgentCore::Gateway::"<agent-gateway-arn>"
);

permit(
  principal == AgentCore::OAuthUser::"<agent-client-id>",
  action == AgentCore::Action::"ApprovalService___record_approval",
  resource == AgentCore::Gateway::"<agent-gateway-arn>"
) when { context.input has packet_id && context.input has packet_hash };

permit(
  principal is AgentCore::OAuthUser,
  action == AgentCore::Action::"ReviewerTools___record_adverse_determination",
  resource == AgentCore::Gateway::"<reviewer-gateway-arn>"
) when { principal.hasTag("pa_role") && principal.getTag("pa_role") == "clinician" };
